{
  // https://nuxt.com/docs/guide/concepts/typescript
  "extends": "./.nuxt/tsconfig.json"
}

import { field, group } from "@nuxthq/studio/theme";

export default defineNuxtSchema({
  appConfig: {
    ui: group({
      title: "UI",
      description: "UI Customization.",
      icon: "i-mdi-palette-outline",
      fields: {
        icons: group({
          title: "Icons",
          description: "Manage icons used in UI Pro.",
          icon: "i-mdi-application-settings-outline",
          fields: {
            search: field({
              type: "icon",
              title: "Search Bar",
              description: "Icon to display in the search bar.",
              icon: "i-mdi-magnify",
              default: "i-heroicons-magnifying-glass-20-solid",
            }),
            dark: field({
              type: "icon",
              title: "Dark mode",
              description: "Icon of color mode button for dark mode.",
              icon: "i-mdi-moon-waning-crescent",
              default: "i-heroicons-moon-20-solid",
            }),
            light: field({
              type: "icon",
              title: "Light mode",
              description: "Icon of color mode button for light mode.",
              icon: "i-mdi-white-balance-sunny",
              default: "i-heroicons-sun-20-solid",
            }),
            external: field({
              type: "icon",
              title: "External Link",
              description: "Icon for external link.",
              icon: "i-mdi-arrow-top-right",
              default: "i-heroicons-arrow-up-right-20-solid",
            }),
            chevron: field({
              type: "icon",
              title: "Chevron",
              description: "Icon for chevron.",
              icon: "i-mdi-chevron-down",
              default: "i-heroicons-chevron-down-20-solid",
            }),
            hash: field({
              type: "icon",
              title: "Hash",
              description: "Icon for hash anchors.",
              icon: "i-ph-hash",
              default: "i-heroicons-hashtag-20-solid",
            }),
          },
        }),
        primary: field({
          type: "string",
          title: "Primary",
          description: "Primary color of your UI.",
          icon: "i-mdi-palette-outline",
          default: "green",
          required: [
            "sky",
            "mint",
            "rose",
            "amber",
            "violet",
            "emerald",
            "fuchsia",
            "indigo",
            "lime",
            "orange",
            "pink",
            "purple",
            "red",
            "teal",
            "yellow",
            "green",
            "blue",
            "cyan",
            "gray",
            "white",
            "black",
          ],
        }),
        gray: field({
          type: "string",
          title: "Gray",
          description: "Gray color of your UI.",
          icon: "i-mdi-palette-outline",
          default: "slate",
          required: ["slate", "cool", "zinc", "neutral", "stone"],
        }),
      },
    }),
    seo: group({
      title: "SEO",
      description: "SEO configuration.",
      icon: "i-ph-app-window",
      fields: {
        siteName: field({
          type: "string",
          title: "Site Name",
          description:
            "Name used in ogSiteName and used as second part of your page title (My page title - Nuxt UI Pro).",
          icon: "i-mdi-web",
          default: [],
        }),
      },
    }),
    header: group({
      title: "Header",
      description: "Header configuration.",
      icon: "i-mdi-page-layout-header",
      fields: {
        logo: group({
          title: "Logo",
          description: "Header logo configuration.",
          icon: "i-mdi-image-filter-center-focus-strong-outline",
          fields: {
            light: field({
              type: "media",
              title: "Light Mode Logo",
              description: "Pick an image from your gallery.",
              icon: "i-mdi-white-balance-sunny",
              default: "",
            }),
            dark: field({
              type: "media",
              title: "Dark Mode Logo",
              description: "Pick an image from your gallery.",
              icon: "i-mdi-moon-waning-crescent",
              default: "",
            }),
            alt: field({
              type: "string",
              title: "Alt",
              description: "Alt to display for accessibility.",
              icon: "i-mdi-alphabet-latin",
              default: "",
            }),
          },
        }),
        search: field({
          type: "boolean",
          title: "Search Bar",
          description: "Hide or display the search bar.",
          icon: "i-mdi-magnify",
          default: true,
        }),
        colorMode: field({
          type: "boolean",
          title: "Color Mode",
          description: "Hide or display the color mode button in your header.",
          icon: "i-mdi-moon-waning-crescent",
          default: true,
        }),
        links: field({
          type: "array",
          title: "Links",
          description: "Array of link object displayed in header.",
          icon: "i-mdi-link-variant",
          default: [],
        }),
      },
    }),
    footer: group({
      title: "Footer",
      description: "Footer configuration.",
      icon: "i-mdi-page-layout-footer",
      fields: {
        credits: group({
          title: "Credits",
          description: "Credits configuration.",
          icon: "i-mdi-credit-card-outline",
          fields: {
            label: field({
              type: "string",
              title: "Label",
              description: "Text to display as label of the credits.",
              icon: "i-mdi-format-title",
              default: "",
            }),
            to: field({
              type: "string",
              title: "Link",
              description: "URL of the credits link.",
              icon: "i-mdi-link-variant",
              default: "",
            }),
          },
        }),
        colorMode: field({
          type: "boolean",
          title: "Color Mode",
          description: "Hide or display the color mode button in the footer.",
          icon: "i-mdi-moon-waning-crescent",
          default: false,
        }),
        links: field({
          type: "array",
          title: "Links",
          description: "Array of link object displayed in footer.",
          icon: "i-mdi-link-variant",
          default: [],
        }),
      },
    }),
    toc: group({
      title: "Table of contents",
      description: "TOC configuration.",
      icon: "i-mdi-table-of-contents",
      fields: {
        title: field({
          type: "string",
          title: "Title",
          description: "Text to display as title of the main toc.",
          icon: "i-mdi-format-title",
          default: "",
        }),
        bottom: group({
          title: "Bottom",
          description: "Bottom TOC configuration.",
          icon: "i-mdi-table-of-contents",
          fields: {
            title: field({
              type: "string",
              title: "Title",
              description: "Text to display as title of the bottom toc.",
              icon: "i-mdi-format-title",
              default: "",
            }),
            edit: field({
              type: "string",
              title: "Edit Page Link",
              description: "URL of your repository content folder.",
              icon: "i-ph-note-pencil",
              default: "",
            }),
            links: field({
              type: "array",
              title: "Links",
              description: "Array of link object displayed in bottom toc.",
              icon: "i-mdi-link-variant",
              default: [],
            }),
          },
        }),
      },
    }),
  },
});

// https://nuxt.com/docs/api/configuration/nuxt-config
export default defineNuxtConfig({
  extends: ["@nuxt/ui-pro"],
  modules: [
    "@nuxt/content",
    "@nuxt/ui",
    "@nuxthq/studio",
    "@nuxtjs/fontaine",
    "@nuxtjs/google-fonts",
    "nuxt-og-image",
    "@nuxthq/studio",
    "@nuxt/image",
  ],
  colorMode: {
    preference: 'dark',
  },
  hooks: {
    // Define `@nuxt/ui` components as global to use them in `.md` (feel free to add those you need)
    "components:extend": (components) => {
      const globals = components.filter((c) =>
        ["UButton", "UIcon"].includes(c.pascalName)
      );

      globals.forEach((c) => (c.global = true));
    },
  },
  ui: {
    icons: ["heroicons", "simple-icons"],
  },
  // Fonts
  fontMetrics: {
    fonts: ["DM Sans"],
  },
  googleFonts: {
    display: "swap",
    download: true,
    families: {
      "DM+Sans": [400, 500, 600, 700],
    },
  },
  routeRules: {
    "/api/search.json": { prerender: true },
    "/docs": {
      redirect: { to: "/welcome/feature-list", statusCode: 302 },
    },
    "/config-v2": {
      redirect: { to: "/getting-started/configuration#legacy-configuration", statusCode: 301 },
    },
  },
  devtools: {
    enabled: true,
  },
  typescript: {
    strict: false,
  },
  uiPro: { license: "oss" },
});

